import java.util.ArrayList;
import java.util.Arrays;

public class Probe {
    public static void main(String[] args) {
        var attempts = new ArrayList<String>();
        var audit = new AuditHandle(attempts);
        var lease = new Lease(attempts);
        try { Owner.use(audit, lease); }
        catch (Throwable thrown) {
            System.out.println("escaped=" + thrown.getClass().getName());
            System.out.println("sameAsOperation=" + (thrown == lease.operationFailure));
            System.out.println("cause=" + thrown.getCause());
            System.out.println("suppressed=" + Arrays.toString(thrown.getSuppressed()));
        }
        System.out.println("closeAttempts=" + attempts);
    }
}

